#!/usr/bin/env node
// Validate a Tauri updater `latest.json` (generated by tauri-action).
// Usage: node scripts/validate-updater-manifest.mjs <latest.json> <expected-version>
// Checks: valid JSON, version match, platform entries, HTTPS URLs,
// signatures present, no downgrade (expected >= current tag implied by name).
import { readFileSync } from "node:fs";

const [file, expected] = process.argv.slice(2);
if (!file || !expected) {
  console.error("usage: validate-updater-manifest.mjs <latest.json> <expected-version>");
  process.exit(2);
}

let manifest;
try {
  manifest = JSON.parse(readFileSync(file, "utf8"));
} catch (e) {
  console.error(`FAIL: invalid JSON: ${e.message}`);
  process.exit(1);
}

const failures = [];
const ok = (cond, msg) => {
  console.log(`${cond ? "PASS" : "FAIL"}: ${msg}`);
  if (!cond) failures.push(msg);
};

ok(typeof manifest.version === "string", "version field present");
ok(manifest.version === expected, `version == ${expected} (got ${manifest.version})`);
ok(manifest.platforms && typeof manifest.platforms === "object", "platforms map present");

const entries = Object.entries(manifest.platforms ?? {});
ok(entries.length > 0, `at least one platform entry (got ${entries.length})`);

for (const [platform, p] of entries) {
  ok(typeof p.url === "string" && p.url.startsWith("https://"), `${platform}: HTTPS url`);
  ok(
    typeof p.signature === "string" && p.signature.length > 32,
    `${platform}: signature present`,
  );
  ok(!/localhost|^http:\/\//.test(p.url), `${platform}: no insecure/local URL`);
}

ok(!failures.length, failures.length ? `${failures.length} failure(s)` : "manifest valid");
process.exit(failures.length ? 1 : 0);
